namespace DcxManager.Hetzner;

/// <summary>
/// The parts of the Hetzner Cloud API v1 the app exposes (ADR-028), taken from the official OpenAPI spec
/// (docs.hetzner.cloud/cloud.spec.json, 2026-10): paths, request fields, enums and required values are the spec's. Views and
/// forms are generated by the shared cloud engine (ADR-020) exactly like Vultr's and Contabo's. Every change answers with
/// a Hetzner action that <see cref="HetznerClient"/> follows to the end before the screen reports it.
/// Metrics (servers, load balancers) are summarised by <see cref="HetznerProvider"/> (ADR-031).
/// Not exposed (deliberately): request_console (needs a VNC-over-WebSocket client the app doesn't have), and the
/// separate Robot (dedicated servers) and Storage Box APIs, which have their own credentials and resource models.
/// </summary>
public static class HetznerCatalog
{
    // ---- lookups ------------------------------------------------------------------------------------------------------
    public static readonly Lookup Locations = new("/locations", "locations", "name", "name", "city", "network_zone");
    public static readonly Lookup ServerTypes = new("/server_types", "server_types", "name", "name", "cores", "memory", "disk", "architecture");
    public static readonly Lookup Images = new("/images?status=available", "images", "id", "description", "type", "architecture");
    public static readonly Lookup SshKeys = new("/ssh_keys", "ssh_keys", "id", "name", "fingerprint");
    public static readonly Lookup Servers = new("/servers", "servers", "id", "name", "public_net.ipv4.ip", "status");
    public static readonly Lookup Networks = new("/networks", "networks", "id", "name", "ip_range");
    public static readonly Lookup PlacementGroups = new("/placement_groups", "placement_groups", "id", "name", "type");
    public static readonly Lookup Isos = new("/isos", "isos", "name", "description", "type", "architecture");
    public static readonly Lookup LbTypes = new("/load_balancer_types", "load_balancer_types", "name", "name", "max_targets", "max_services");

    public static readonly string[] NetworkZones = { "eu-central", "us-east", "us-west", "ap-southeast" };
    private static Field Labels(bool update = false) => new("labels", "Labels (JSON)", FieldKind.Json, Default: update ? "{json:labels}" : "{}", Hint: "key/value pairs, e.g. {\"env\": \"lab\"}");
    private static ActionDef Protection(string root, bool rebuild = false) => new("🛡 Protection…", "POST", $"/{root}/{{id}}/actions/change_protection",
        rebuild
            ? new[] { new Field("delete", "Protect against deletion", FieldKind.Bool, Default: "{protection.delete}"), new Field("rebuild", "Protect against rebuild", FieldKind.Bool, Default: "{protection.rebuild}") }
            : new[] { new Field("delete", "Protect against deletion", FieldKind.Bool, Default: "{protection.delete}") },
        Confirm: "Change the protection of {name}?", Tip: "While protected, Hetzner refuses to delete (or rebuild) it");

    // ---- compute --------------------------------------------------------------------------------------------------------
    // Server states (spec): running, initializing, starting, stopping, off, deleting, migrating, rebuilding, unknown.
    public static readonly ResourceDef Server = new()
    {
        Title = "Servers", Group = "Compute", Path = "/servers", Key = "servers", IdField = "id", NameField = "name", Icon = "▣",
        StatusField = "status", IsInstance = true, TypeToDelete = true, UpdateMethod = "PUT",
        Description = "Hetzner Cloud servers of this project. Creating one is billed hourly up to the monthly cap; deleting removes its disks (snapshots and backups stay until deleted).",
        Columns = new Col[]
        {
            new("name", "Name", 150), new("status", "Status", 75), new("public_net.ipv4.ip", "IPv4", 120), new("server_type.name", "Type", 70),
            new("location.name", "Location", 70), new("image.description", "Image", 140), new("server_type.cores", "vCPU", 45), new("server_type.memory", "RAM GB", 60),
            new("primary_disk_size", "Disk GB", 60), new("protection.delete", "Protected", 70), new("rescue_enabled", "Rescue", 55), new("id", "Id", 90),
        },
        Create = new Field[]
        {
            new("name", "Name", Required: true, Hint: "a valid hostname, e.g. web-01"),
            new("server_type", "Server type", FieldKind.Lookup, true, Lookup: ServerTypes),
            new("image", "Image", FieldKind.Lookup, true, Lookup: Images, Hint: "system image, app, snapshot or backup"),
            new("location", "Location", FieldKind.Lookup, Lookup: Locations, Hint: "empty = Hetzner chooses"),
            new("ssh_keys", "SSH keys", FieldKind.MultiLookup, Lookup: SshKeys, Hint: "strongly recommended; without one Hetzner e-mails a root password and the app shows it once"),
            new("placement_group", "Placement group", FieldKind.Lookup, Lookup: PlacementGroups),
            new("start_after_create", "Start after create", FieldKind.Bool, Default: "true"),
            new("user_data", "Cloud-init user data", FieldKind.Multiline, Hint: "optional #cloud-config"),
            new("networks", "Private networks (ids, JSON)", FieldKind.Json, Hint: "optional, e.g. [123]"),
            new("firewalls", "Firewalls (JSON)", FieldKind.Json, Hint: "optional, e.g. [{\"firewall\": 38}]"),
            Labels(),
        },
        CreateConfirm = "This CREATES a billed Hetzner server “{form.name}” ({form.server_type}) in this project. Continue?",
        Update = new Field[] { new("name", "Name", Required: true, Default: "{name}"), Labels(true) },
        Actions = new ActionDef[]
        {
            new("▶ Power on", "POST", "/servers/{id}/actions/poweron", When: "off", Await: "running"),
            new("⏻ Shut down", "POST", "/servers/{id}/actions/shutdown", Confirm: "Shut down {name} ({public_net.ipv4.ip}) gracefully (ACPI)?", When: "running", Await: "off",
                Tip: "Graceful shutdown through the operating system"),
            new("↻ Reboot", "POST", "/servers/{id}/actions/reboot", Confirm: "Reboot {name} ({public_net.ipv4.ip}) gracefully (ACPI)?", When: "running", Await: "running"),
            new("■ Power off", "POST", "/servers/{id}/actions/poweroff", Confirm: "Power off {name} ({public_net.ipv4.ip})? This cuts power like pulling the plug: unsaved data can be lost.", Danger: true, When: "running", Await: "off"),
            new("⌨ SSH", "", "", Special: "ssh", Tip: "Open a terminal (uses or creates a saved host for this IP)"),
            new("＋ Add to hosts", "", "", Special: "addhost"),
            new("⚡ Reset (hard)", "POST", "/servers/{id}/actions/reset", Confirm: "Hard-reset {name}? Like pressing the reset button: unsaved data can be lost.", Danger: true, When: "running", Await: "running"),
            new("Rescue mode…", "POST", "/servers/{id}/actions/enable_rescue", new[]
            {
                new Field("type", "Rescue system", FieldKind.Select, Default: "linux64", Options: new[] { "linux64" }),
                new Field("ssh_keys", "SSH keys for rescue", FieldKind.MultiLookup, Lookup: SshKeys),
            }, Confirm: "Enable the rescue system for {name}? It boots into rescue at the NEXT reboot (reboot it afterwards). The root password, if any, is shown once.", Danger: true, ShowResult: true,
                When: "running,off"),
            new("Disable rescue", "POST", "/servers/{id}/actions/disable_rescue", Confirm: "Disable the rescue system for {name}? The next reboot starts the installed system.", When: "running,off"),
            new("Rebuild…", "POST", "/servers/{id}/actions/rebuild", new[]
            {
                new Field("image", "Image", FieldKind.Lookup, true, Lookup: Images), new Field("user_data", "Cloud-init user data", FieldKind.Multiline),
            }, Confirm: "Rebuild {name}? Its disk is WIPED and the image installed again. A new root password (if any) is shown once.", Danger: true, TypeToConfirm: "{name}", ShowResult: true,
                When: "running,off"),
            new("Change type…", "POST", "/servers/{id}/actions/change_type", new[]
            {
                new Field("server_type", "New server type", FieldKind.Lookup, true, Lookup: ServerTypes),
                new Field("upgrade_disk", "Also grow the disk (then it can never be downgraded again)", FieldKind.Bool, Default: "false"),
            }, Confirm: "Change the type of {name}? The server must stay off until it finishes; billing follows the new type.", Danger: true, When: "off",
                Tip: "Resize (the server must be powered off)"),
            new("Create image…", "POST", "/servers/{id}/actions/create_image", new[]
            {
                new Field("description", "Description", Default: "{name} {now}"),
                new Field("type", "Type", FieldKind.Select, Default: "snapshot", Options: new[] { "snapshot", "backup" }), Labels(),
            }, Confirm: "Create an image of {name}? Snapshots are billed per GB; take them while the server is off for a consistent disk.", When: "running,off",
                Tip: "Snapshot (or backup) of the server's disk"),
            new("Enable backups", "POST", "/servers/{id}/actions/enable_backup", Confirm: "Enable daily backups for {name}? Billed at 20 % of the server price.", When: "running,off"),
            new("Disable backups…", "POST", "/servers/{id}/actions/disable_backup", Confirm: "Disable backups for {name}? ALL its backups are deleted immediately.", Danger: true, TypeToConfirm: "{name}"),
            new("Attach ISO…", "POST", "/servers/{id}/actions/attach_iso", new[] { new Field("iso", "ISO", FieldKind.Lookup, true, Lookup: Isos) },
                Confirm: "Attach the ISO to {name}? It boots from it at the next reboot."),
            new("Detach ISO", "POST", "/servers/{id}/actions/detach_iso", Confirm: "Detach the ISO from {name}?"),
            new("Attach to network…", "POST", "/servers/{id}/actions/attach_to_network", new[]
            {
                new Field("network", "Network", FieldKind.Lookup, true, Lookup: Networks), new Field("ip", "Private IP", Hint: "empty = the next free one"),
            }, Confirm: "Attach {name} to the private network?"),
            new("Detach from network…", "POST", "/servers/{id}/actions/detach_from_network", new[] { new Field("network", "Network", FieldKind.Lookup, true, Lookup: Networks) },
                Confirm: "Detach {name} from the private network? Traffic over it stops.", Danger: true),
            new("Add to placement group…", "POST", "/servers/{id}/actions/add_to_placement_group", new[] { new Field("placement_group", "Placement group", FieldKind.Lookup, true, Lookup: PlacementGroups) },
                Confirm: "Add {name} to the placement group? The server must be off.", When: "off"),
            new("Remove from placement group", "POST", "/servers/{id}/actions/remove_from_placement_group", Confirm: "Remove {name} from its placement group?", When: "off"),
            new("Reverse DNS…", "POST", "/servers/{id}/actions/change_dns_ptr", new[]
            {
                new Field("ip", "IP", Required: true, Default: "{public_net.ipv4.ip}"), new Field("dns_ptr", "Reverse DNS name", Hint: "empty = reset to Hetzner's default"),
            }, Confirm: "Change the reverse DNS of {name}?"),
            Protection("servers", rebuild: true),
            new("Alias IPs…", "POST", "/servers/{id}/actions/change_alias_ips", new[]
            {
                new Field("network", "Network", FieldKind.Lookup, true, Lookup: Networks), new Field("alias_ips", "Alias IPs (JSON)", FieldKind.Json, true, "[]", Hint: "the complete new list, e.g. [\"10.0.1.5\"]; [] removes all"),
            }, Confirm: "Replace the alias IPs of {name} in that network?"),
            new("📈 Metrics (last hour)", "GET", "/servers/{id}/metrics", Special: "metrics", Tip: "CPU, disk and network averages over the last hour (Hetzner keeps metrics for 30 days)"),
            new("Reset root password…", "POST", "/servers/{id}/actions/reset_password",
                Confirm: "Reset the root password of {name}? Needs the qemu guest agent in the server. The new password is shown once and not stored.", Danger: true, ShowResult: true, When: "running"),
        },
        Children = new[] { ("Actions", ServerActions) },
    };

